function gerarGraficoSVG(data) {
  const labels = ['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'];
  const maxVal = Math.max(...data, 1);
  const W = 920, H = 340; 
  const mL = 40, mR = 15, mT = 12, mB = 40;
  const cW = W - mL - mR;
  const cH = H - mT - mB;
  const barGap = cW / 7;
  const barW   = barGap * 0.55;
  const yTicks = maxVal <= 4
    ? [0, 1, 2, 3, 4].filter(t => t <= maxVal + 1)
    : [0, Math.round(maxVal / 2), maxVal];

  let svg = '<svg viewBox="0 0 ' + W + ' ' + H + '" xmlns="http://www.w3.org/2000/svg" width="100%" height="' + H + '">';
  yTicks.forEach(tick => {
    const y = (mT + cH - (tick / maxVal) * cH).toFixed(1);
    svg += '<line x1="' + mL + '" y1="' + y + '" x2="' + (W - mR) + '" y2="' + y + '" stroke="#F0F0F0" stroke-width="2"/>';
    svg += '<text x="' + (mL - 10) + '" y="' + (parseFloat(y) + 6).toFixed(1) + '" text-anchor="end" font-size="18" fill="#888" font-family="Nunito,sans-serif">' + tick + '</text>';
  });
  data.forEach((val, i) => {
    const barH = val > 0 ? Math.max((val / maxVal) * cH, 5) : 0;
    const x    = (mL + i * barGap + (barGap - barW) / 2).toFixed(1);
    const y    = (mT + cH - barH).toFixed(1);
    const cor  = (val === maxVal && val > 0) ? '#A09BB5' : '#7B6BB5';
    if (barH > 0) {
      svg += '<rect x="' + x + '" y="' + y + '" width="' + barW.toFixed(1) + '" height="' + barH.toFixed(1) + '" rx="8" fill="' + cor + '"/>';
    }
    const lx = (mL + i * barGap + barGap / 2).toFixed(1);
    svg += '<text x="' + lx + '" y="' + (H - 5) + '" text-anchor="middle" font-size="22" font-weight="800" fill="#888" font-family="Nunito,sans-serif">' + labels[i] + '</text>';
  });
  svg += '</svg>';
  return svg;
}

